//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::array::empty_with_capacity`; the
//! native twin is `benches/native/Bench/ArrayEmptyWithCapacity.lean`.
//! Array.mkEmpty: one allocation of the object's 24 + 8c bytes on both sides

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::array;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match array::empty_with_capacity(
                array::WORD_ELEMENT_BYTES,
                nat_unbox(nat_box((x >> 4) & 0xFF)),
            ) {
                Ok(c) => black_box(new_object(24 + 8 * c as u64)).len() as u64 - 24,
                Err(p) => end(p),
            },
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
